import{Z as t,e as n,f as o,a0 as a}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Paddle","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/paddle.md","filePath":"integrations/payments/paddle.md","lastUpdated":1780377007000}'),i={name:"integrations/payments/paddle.md"};function r(s,e,l,d,c,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="paddle" tabindex="-1">Paddle <a class="header-anchor" href="#paddle" aria-label="Permalink to &quot;Paddle&quot;">​</a></h1><p>Connect Paddle to take payments through the provider configured for your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Paddle</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-paddle-api" tabindex="-1">Step 2. Connect to the Paddle API <a class="header-anchor" href="#step-2-connect-to-the-paddle-api" aria-label="Permalink to &quot;Step 2. Connect to the Paddle API&quot;">​</a></h3><ol><li>Go to the <a href="https://vendors.paddle.com" target="_blank">Paddle Dashboard</a>.</li><li>Navigate to <strong>Developer Tools</strong> → <strong>Authentication</strong>.</li><li>Click the <strong>New API Key</strong> button.</li><li>Copy the <strong>API Key</strong> from Paddle and paste in the <strong>API Key</strong> field in Formie.</li><li>Navigate to <strong>Client-side tokens</strong>.</li><li>Click the <strong>New Client-side Token</strong> button.</li><li>Copy the <strong>Token</strong> from Paddle and paste in the <strong>Client Side Token</strong> field in Formie.</li></ol><p>The API key needs permission to create products, prices and transactions, and to read transactions. Formie creates the transaction before opening checkout and verifies its final status, currency and amount with Paddle before completing the submission. Configure an approved default payment link in Paddle&#39;s checkout settings so its API can create checkout transactions.</p><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-field-setting" tabindex="-1">Step 4. Field Setting <a class="header-anchor" href="#step-4-field-setting" aria-label="Permalink to &quot;Step 4. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select Paddle for the <strong>Payment Provider</strong>.</li></ol><p>The Paddle payment integration supports only once-off payments.</p><p>Keep the configured amount and currency unchanged while a checkout is in progress. If you change them, check the original transaction in Paddle before starting another payment. A completed payment must cover the configured amount; discounts that reduce the collected total below that amount cannot complete the submission.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Complete a test payment and inspect both the saved submission and the provider’s transaction record. Confirm the amount, currency and final payment state before enabling live payments.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',16)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
